// Generated by scripts/sync-examples.ts from scripts/example-app. Do not edit.
// Times each benchmark kernel compiled by Lucent against the same TypeScript
// run as JavaScript by Hermes, after checking both return the same checksum.
import { useEffect, useState } from "react";
import { Pressable, ScrollView, Text, View } from "react-native";
import * as js from "../bench/kernels";
import { sizes } from "../bench/sizes";
import * as native from "../lucent/kernels.lucent";
import { styles } from "./styles";
import { type Kernel, timeKernel } from "./timeKernel";

/** Phones run JavaScript slower than a desktop; keep a run under a minute. */
const SCALE = 0.25;

type Row = { name: string; n: number; js: number; native: number; same: boolean };

const ms = (v: number) => (v < 10 ? v.toFixed(2) : v.toFixed(0));

export function BenchScreen() {
  const [rows, setRows] = useState<Row[]>([]);
  const [running, setRunning] = useState(false);

  async function run() {
    setRunning(true);
    setRows([]);
    const out: Row[] = [];
    for (const name of Object.keys(sizes) as (keyof typeof sizes)[]) {
      // Let the list render between kernels.
      await new Promise<void>((r) => setTimeout(() => r(), 30));
      const n = Math.max(1, Math.round(sizes[name] * SCALE));
      const fjs = js[name] as Kernel;
      const fnative = native[name] as Kernel;
      const same = fjs(n) === fnative(n);
      out.push({ name, n, js: timeKernel(fjs, n), native: timeKernel(fnative, n), same });
      setRows([...out]);
    }
    setRunning(false);
  }

  useEffect(() => {
    void run();
  }, []);

  const done = !running && rows.length === Object.keys(sizes).length;
  const allSame = rows.every((r) => r.same);
  const geomean = Math.exp(
    rows.reduce((acc, r) => acc + Math.log(r.js / Math.max(r.native, 0.001)), 0) /
      Math.max(rows.length, 1),
  );

  return (
    <>
      <View style={styles.header}>
        <Text style={styles.title}>Lucent vs JavaScript</Text>
        <Text style={styles.subtitle}>
          Same TypeScript: compiled to C++ by Lucent, or run by Hermes. Best of 3.
        </Text>
        {__DEV__ ? (
          <Text style={styles.warn}>
            Debug build: use a Release build for representative numbers.
          </Text>
        ) : null}
        <Text
          testID="bench-summary"
          style={[styles.summary, done && (allSame ? styles.ok : styles.bad)]}
        >
          {running
            ? "Running…"
            : done
              ? allSame
                ? `${geomean.toFixed(1)}x faster (geometric mean)`
                : "RESULTS DIFFER"
              : ""}
        </Text>
        <Pressable
          testID="bench-run"
          disabled={running}
          onPress={run}
          style={({ pressed }) => [styles.button, (pressed || running) && styles.pressed]}
        >
          <Text style={styles.buttonText}>Run again</Text>
        </Pressable>
      </View>
      <ScrollView contentContainerStyle={styles.list}>
        <View style={styles.benchHead}>
          <Text style={styles.benchHeadName}>kernel</Text>
          <Text style={styles.benchHeadCell}>JS ms</Text>
          <Text style={styles.benchHeadCell}>Lucent ms</Text>
          <Text style={styles.benchHeadCell}>speedup</Text>
        </View>
        {rows.map((r) => (
          <View key={r.name} style={styles.benchRow}>
            <Text style={styles.benchName}>{r.same ? r.name : `❌ ${r.name}`}</Text>
            <Text style={styles.benchCell}>{ms(r.js)}</Text>
            <Text style={styles.benchCell}>{ms(r.native)}</Text>
            <Text style={styles.benchSpeedup}>
              {(r.js / Math.max(r.native, 0.001)).toFixed(1)}x
            </Text>
          </View>
        ))}
      </ScrollView>
    </>
  );
}
